using namespace std;
int cmp = 0;
int a[7] = {5, 1, 4, 2, 8, 9, 3};
int tmp[7];
void msort(int lo, int hi) {
  if (hi - lo < 1) return;
  int mid = (lo + hi) / 2;
  msort(lo, mid);
  msort(mid + 1, hi);
  int i = lo, j = mid + 1, k = lo;
  while (i <= mid && j <= hi) {
    cmp++;
    if (a[i] <= a[j]) tmp[k++] = a[i++];
    else tmp[k++] = a[j++];
  }
  while (i <= mid) tmp[k++] = a[i++];
  while (j <= hi) tmp[k++] = a[j++];
  for (int x = lo; x <= hi; x++) a[x] = tmp[x];
}
int main() {
  msort(0, 6);
  for (int i = 0; i < 7; i++) cout << a[i] << " ";
  cout << "| " << cmp << endl;
  return 0;
